-- AUTO BLOCK TSB - FIXED VERSION (NO FALSE TRIGGER & NO LAG) local Players = game:GetService("Players") local VirtualInputManager = game:GetService("VirtualInputManager") local CoreGui = game:GetService("CoreGui") local RunService = game:GetService("RunService") local LocalPlayer = Players.LocalPlayer local AutoBlockEnabled = true local DistanceThreshold = 14 -- Giảm khoảng cách lại chút để tránh quét oan người đứng gần -- Danh sách ID animation đòn đánh chuẩn xác của TSB (loại bỏ idle/run) local StrictAttackAnimations = { ["rbxassetid://10469493270"] = true, ["rbxassetid://10469630950"] = true, ["rbxassetid://10469639222"] = true, ["rbxassetid://10469643643"] = true, ["rbxassetid://10471336737"] = true, ["rbxassetid://12510170068"] = true, ["rbxassetid://12509122394"] = true, ["rbxassetid://12509129590"] = true, } local isBlocking = false local function startBlock() if not isBlocking then isBlocking = true VirtualInputManager:SendKeyEvent(true, Enum.KeyCode.F, false, game) end end local function stopBlock() if isBlocking then isBlocking = false VirtualInputManager:SendKeyEvent(false, Enum.KeyCode.F, false, game) end end RunService.RenderStepped:Connect(function() if not AutoBlockEnabled then if isBlocking then stopBlock() end return end local myChar = LocalPlayer.Character if not myChar or not myChar:FindFirstChild("HumanoidRootPart") then return end local myPos = myChar.HumanoidRootPart.Position local shouldBlock = false for _, player in ipairs(Players:GetPlayers()) do if player ~= LocalPlayer and player.Character and player.Character:FindFirstChild("HumanoidRootPart") then local enemyChar = player.Character local enemyPos = enemyChar.HumanoidRootPart.Position local dist = (myPos - enemyPos).Magnitude if dist <= DistanceThreshold then local humanoid = enemyChar:FindFirstChildOfClass("Humanoid") if humanoid then local animator = humanoid:FindFirstChildOfClass("Animator") if animator then for _, track in ipairs(animator:GetPlayingAnimationTracks()) do if track.Animation then local animId = track.Animation.AnimationId -- Chỉ bắt đúng animation đòn đánh thực tế, bỏ qua tốc độ chạy if StrictAttackAnimations[animId] then shouldBlock = true break end end end end end end end end if shouldBlock then startBlock() else stopBlock() end end) if CoreGui:FindFirstChild("TSB_AutoBlock_UI") then CoreGui.TSB_AutoBlock_UI:Destroy() end local ScreenGui = Instance.new("ScreenGui") ScreenGui.Name = "TSB_AutoBlock_UI" ScreenGui.Parent = CoreGui local MainFrame = Instance.new("Frame") MainFrame.Size = UDim2.new(0, 160, 0, 70) MainFrame.Position = UDim2.new(0.05, 0, 0.4, 0) MainFrame.BackgroundColor3 = Color3.fromRGB(20, 20, 20) MainFrame.BorderSizePixel = 0 MainFrame.Active = true MainFrame.Draggable = true MainFrame.Parent = ScreenGui local UICorner = Instance.new("UICorner") UICorner.CornerRadius = UDim.new(0, 8) UICorner.Parent = MainFrame local Title = Instance.new("TextLabel") Title.Size = UDim2.new(1, 0, 0, 25) Title.Text = "AUTO BLOCK TSB" Title.TextColor3 = Color3.fromRGB(255, 255, 255) Title.TextSize = 12 Title.Font = Enum.Font.SourceSansBold Title.BackgroundColor3 = Color3.fromRGB(35, 35, 35) Title.Parent = MainFrame local ToggleBtn = Instance.new("TextButton") ToggleBtn.Size = UDim2.new(0.85, 0, 0, 30) ToggleBtn.Position = UDim2.new(0.075, 0, 0.48, 0) ToggleBtn.Text = "AUTO BLOCK: ON" ToggleBtn.BackgroundColor3 = Color3.fromRGB(0, 170, 80) ToggleBtn.TextColor3 = Color3.fromRGB(255, 255, 255) ToggleBtn.Font = Enum.Font.SourceSansBold ToggleBtn.TextSize = 12 ToggleBtn.Parent = MainFrame local BtnCorner = Instance.new("UICorner") BtnCorner.CornerRadius = UDim.new(0, 6) BtnCorner.Parent = ToggleBtn ToggleBtn.MouseButton1Click:Connect(function() AutoBlockEnabled = not AutoBlockEnabled if AutoBlockEnabled then ToggleBtn.Text = "AUTO BLOCK: ON" ToggleBtn.BackgroundColor3 = Color3.fromRGB(0, 170, 80) else ToggleBtn.Text = "AUTO BLOCK: OFF" ToggleBtn.BackgroundColor3 = Color3.fromRGB(170, 40, 40) stopBlock() end end)
